def get_announcements(session: requests.Session, telemetry: bool=True,
    with_telemetry: Any=None) ->List[Dict[str, str]]:
    """
    Retrieves announcements from the server.

    Args:
        session (requests.Session): The requests session.
        telemetry (bool): Whether to include telemetry data.
        with_telemetry (Any): Additional telemetry data.

    Returns:
        List[Dict[str, str]]: The list of announcements.
    """
    try:
        url = f"{DATA_API_BASE_URL}announcements/"

        telemetry_data = {
            'telemetry': json.dumps(build_telemetry_data(telemetry=telemetry),
                                    default=pydantic_encoder)}

        r = session.post(url=url, timeout=REQUEST_TIMEOUT, json=telemetry_data)

        if r.status_code != 200:
            return []

        data = r.json()

        if not isinstance(data, dict) or 'announcements' not in data:
            return []

        announcements = data.get('announcements', [])

        if not isinstance(announcements, list):
            return []

        return announcements

    except requests.exceptions.RequestException:
        return []
    except json.JSONDecodeError:
        return []
    except Exception:
        return []
